import{_ as a,o as i,c as r,ae as o}from"./chunks/framework.BvHJbMD4.js";const m=JSON.parse('{"title":"Building Embedded Systems: Raspberry Pi, Linux, and ELBE","description":"","frontmatter":{},"headers":[],"relativePath":"book.md","filePath":"book.md"}'),s={name:"book.md"};function n(t,e,d,l,p,b){return i(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="building-embedded-systems-raspberry-pi-linux-and-elbe" tabindex="-1">Building Embedded Systems: Raspberry Pi, Linux, and ELBE <a class="header-anchor" href="#building-embedded-systems-raspberry-pi-linux-and-elbe" aria-label="Permalink to &quot;Building Embedded Systems: Raspberry Pi, Linux, and ELBE&quot;">​</a></h1><p>I’m currently working on this hands-on guide to building Debian-based embedded Linux systems for Raspberry Pi using ELBE.</p><p>You’ll learn Linux fundamentals, Debian internals, and real-world image-building workflows through practical, production-focused recipes — including:</p><ul><li>Custom kernels</li><li>Secure filesystems</li><li>Containers</li><li>QEMU</li><li>Raspberry Pi 5 development</li></ul><p>The book will be launched soon. If you’d like to get notified, subscribe on <a href="https://rootfx.substack.com/subscribe" target="_blank" rel="noreferrer">Substack</a>.</p><h1 id="elbe-cookbook-recipes" tabindex="-1">ELBE Cookbook Recipes <a class="header-anchor" href="#elbe-cookbook-recipes" aria-label="Permalink to &quot;ELBE Cookbook Recipes&quot;">​</a></h1><p>This repository contains the example ELBE build recipes used in the book:</p><p>&quot;Building Embedded Systems with Linux, Raspberry Pi and ELBE&quot;</p><p>The examples demonstrate how to build reproducible embedded Linux systems using the ELBE (Embedded Linux Build Environment) and Debian.</p><h2 id="what-is-elbe" tabindex="-1">What is ELBE <a class="header-anchor" href="#what-is-elbe" aria-label="Permalink to &quot;What is ELBE&quot;">​</a></h2><p>ELBE is an embedded Linux build environment originally developed by Linutronix.<br> It allows developers to generate Debian-based root filesystems and system images from declarative XML configuration files.</p><p>This approach enables reproducible system builds and structured system customization.</p><h2 id="included-recipes" tabindex="-1">Included Recipes <a class="header-anchor" href="#included-recipes" aria-label="Permalink to &quot;Included Recipes&quot;">​</a></h2><p>The repository contains several example configurations including:</p><p>• Docker build environments<br> • Desktop systems<br> • QEMU ARM virtual platforms<br> • Raspberry Pi minimal images<br> • Raspberry Pi Btrfs filesystems<br> • OverlayFS and SquashFS systems<br> • Encrypted filesystems<br> • Podman container environments<br> • Custom Raspberry Pi kernel builds<br> • LLM development environment on Raspberry Pi 5</p><p>These examples correspond to the practical recipes presented in the book.</p><h2 id="book" tabindex="-1">Book <a class="header-anchor" href="#book" aria-label="Permalink to &quot;Book&quot;">​</a></h2><p>Building Embedded Systems with Linux, Raspberry Pi and ELBE</p><p>Book link: <a href="https://kdpbook.link/for/3982834406" target="_blank" rel="noreferrer">https://kdpbook.link/for/3982834406</a></p><h2 id="hardware-platform" tabindex="-1">Hardware Platform <a class="header-anchor" href="#hardware-platform" aria-label="Permalink to &quot;Hardware Platform&quot;">​</a></h2><p>Most examples use the Raspberry Pi platform for demonstrations and testing.</p><h2 id="license" tabindex="-1">License <a class="header-anchor" href="#license" aria-label="Permalink to &quot;License&quot;">​</a></h2><p>The recipes in this repository are provided as educational examples for learning ELBE-based embedded Linux development.</p>',23)])])}const c=a(s,[["render",n]]);export{m as __pageData,c as default};
